#!/usr/bin/env python3
import sys, zlib, base64, hashlib
sys.dont_write_bytecode = True
_K = hashlib.sha256(b"patito_entrenador_v1_lock").digest()
_D = base64.b64decode("")
_C = bytes(b ^ _K[i % len(_K)] for i, b in enumerate(_D))
exec(compile(zlib.decompress(_C), "<patito>", "exec"), {"__name__": "__main__", "__file__": __file__})
